import XCTest

class ElementNavigationTest: XCTestCase {
    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    func testNavigateToSessions() throws {
        let app = XCUIApplication()
        app.launch()

        // Wait for dialog to appear
        let cancelButton = app.buttons["Cancel"]
        XCTAssert(cancelButton.waitForExistence(timeout: 5))
        cancelButton.tap()

        // Wait a moment for dialog to close
        Thread.sleep(forTimeInterval: 1)

        // Tap on profile button (the purple A)
        let profileButton = app.buttons.containing(NSPredicate(format: "label CONTAINS 'A'")).element
        if profileButton.exists {
            profileButton.tap()
        }

        // Look for Settings option
        let settingsButton = app.buttons["Settings"].firstMatch
        if settingsButton.waitForExistence(timeout: 5) {
            settingsButton.tap()
        }

        // Look for Sessions/Devices
        let sessionsButton = app.staticTexts["Sessions"].firstMatch
        if sessionsButton.waitForExistence(timeout: 5) {
            sessionsButton.tap()
        }
    }
}
EOF
